import { useQuery, useMutation } from "@tanstack/react-query";
export const useListNfts = (params = {}, options = {}) => useQuery({ queryKey: ["nfts", params], queryFn: async () => [], ...options });
export const useGetNft = (id, options = {}) => useQuery({ queryKey: ["nft", id], queryFn: async () => ({}), ...options });
export const useListCollections = () => useQuery({ queryKey: ["collections"], queryFn: async () => [] });
export const useGetCollection = (id, options = {}) => useQuery({ queryKey: ["collection", id], queryFn: async () => ({}), ...options });
export const useListActivity = (params = {}) => useQuery({ queryKey: ["activity", params], queryFn: async () => [] });
export const useGetMarketplaceStats = () => useQuery({ queryKey: ["stats"], queryFn: async () => ({ totalVolume: "0", totalNfts: 0, totalCollections: 0, uniqueOwners: 0 }) });
export const useListNftOffers = (id, options = {}) => useQuery({ queryKey: ["offers", id], queryFn: async () => [], ...options });
export const useListReceivedOffers = (params, options = {}) => useQuery({ queryKey: ["received-offers", params], queryFn: async () => [], ...options });
export const useCreateNft = () => useMutation({ mutationFn: async (data) => ({}) });
export const useBuyNft = () => useMutation({ mutationFn: async (data) => ({}) });
export const useListNftForSale = () => useMutation({ mutationFn: async (data) => ({}) });
export const useCreateCollection = () => useMutation({ mutationFn: async (data) => ({}) });
export const useMakeOffer = () => useMutation({ mutationFn: async (data) => ({}) });
export const useAcceptOffer = () => useMutation({ mutationFn: async (data) => ({}) });
export const useDeclineOffer = () => useMutation({ mutationFn: async (data) => ({}) });
export const getListNftsQueryKey = (params = {}) => ["nfts", params];
export const getGetNftQueryKey = (id) => ["nft", id];
export const getGetCollectionQueryKey = (id) => ["collection", id];
export const getListReceivedOffersQueryKey = (params) => ["received-offers", params];
export const getListNftOffersQueryKey = (id) => ["offers", id];
